// ─── File: ChatDemo.java ───
// Runnable demo of the server-side core. Simulates two WebSocket servers
// and a shared Redis pub-sub. Each class would be its own file in a real project.
package com.bank.chat;

import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.*;

public class ChatDemo {
    private static final Logger log = Logger.getLogger(ChatDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PubSub pubSub = new PubSub();                 // simulates Redis pub-sub
        MessageStore store = new MessageStore();      // persist-first source of truth
        SequenceGenerator seq = new SequenceGenerator();
        OfflineQueue offlineQueue = new OfflineQueue();
        PushNotifier push = new PushNotifier();

        // Two WebSocket servers, each with its own local connection registry.
        ConnectionRegistry serverA = new ConnectionRegistry("serverA", pubSub);
        ConnectionRegistry serverB = new ConnectionRegistry("serverB", pubSub);

        ChatService chat = new ChatService(store, seq, pubSub, offlineQueue, push);

        // Priya connects on serverA; Rajesh connects on serverB (different servers!)
        serverA.connect("CUR3001", msg -> log.info("→ Priya device sees: " + render(msg)));
        serverB.connect("SAV2001", msg -> log.info("→ Rajesh device sees: " + render(msg)));

        String convo = "SAV2001:CUR3001";
        // Rajesh sends two quick messages (lands on serverB)
        chat.send(convo, "SAV2001", "CUR3001", "Hi Priya, about my home loan", "cid-1");
        chat.send(convo, "SAV2001", "CUR3001", "What documents do you need?", "cid-2");

        // Priya reads them → read receipt syncs back to Rajesh
        chat.markRead(convo, "CUR3001", 2);

        // Priya goes offline; Rajesh sends again → queued + push
        serverA.disconnect("CUR3001");
        chat.send(convo, "SAV2001", "CUR3001", "Also, what is the interest rate?", "cid-3");

        // Priya reconnects and replays missed messages from her last-seen seq (2)
        serverA.connect("CUR3001", msg -> log.info("→ Priya device sees (replay): " + render(msg)));
        chat.replayMissed(convo, "CUR3001", 2);
    }

    static String render(Message m) {
        return "[seq=" + m.sequence + "] " + m.from + ": \"" + m.body + "\"";
    }
}

// ─── model/DeliveryState.java ───
enum DeliveryState { SENT, DELIVERED, READ }

// ─── model/Message.java ───
class Message {
    final String conversationId, from, to, body, clientId;
    final long sequence; final Instant at;
    DeliveryState state = DeliveryState.SENT;
    Message(String conversationId, String from, String to, String body, String clientId, long sequence) {
        this.conversationId = conversationId; this.from = from; this.to = to;
        this.body = body; this.clientId = clientId; this.sequence = sequence; this.at = Instant.now();
    }
}

// ─── store/SequenceGenerator.java ───
// Monotonic per-conversation sequence for ordering.
class SequenceGenerator {
    private final Map<String, AtomicLong> counters = new ConcurrentHashMap<>();
    long next(String conversationId) {
        return counters.computeIfAbsent(conversationId, k -> new AtomicLong(0)).incrementAndGet();
    }
}

// ─── store/MessageStore.java ───
// Durable source of truth. Dedupes by clientId for idempotency.
class MessageStore {
    private static final Logger log = Logger.getLogger(MessageStore.class.getName());
    private final Map<String, List<Message>> byConversation = new ConcurrentHashMap<>();
    private final Set<String> seenClientIds = ConcurrentHashMap.newKeySet();

    synchronized Message persist(Message m) {
        if (!seenClientIds.add(m.clientId)) {        // idempotency: already stored
            log.fine("duplicate clientId " + m.clientId + " ignored");
            return m;
        }
        byConversation.computeIfAbsent(m.conversationId, k -> new ArrayList<>()).add(m);
        log.info("PERSISTED " + m.conversationId + " seq=" + m.sequence + " from " + m.from);
        return m;
    }
    List<Message> since(String conversationId, long afterSeq) {
        return byConversation.getOrDefault(conversationId, List.of()).stream()
                .filter(m -> m.sequence > afterSeq).sorted(Comparator.comparingLong(x -> x.sequence)).toList();
    }
    void updateState(String conversationId, long upToSeq, DeliveryState state) {
        byConversation.getOrDefault(conversationId, List.of()).stream()
                .filter(m -> m.sequence <= upToSeq).forEach(m -> m.state = state);
    }
}

// ─── pubsub/PubSub.java ───
// Simulates Redis pub-sub so a message on one server reaches a socket on another.
class PubSub {
    private final Map<String, List<java.util.function.Consumer<Message>>> subs = new ConcurrentHashMap<>();
    void subscribe(String channel, java.util.function.Consumer<Message> handler) {
        subs.computeIfAbsent(channel, k -> new CopyOnWriteArrayList<>()).add(handler);
    }
    void unsubscribe(String channel) { subs.remove(channel); }
    void publish(String channel, Message m) {
        subs.getOrDefault(channel, List.of()).forEach(h -> h.accept(m));
    }
}

// ─── ws/ConnectionRegistry.java ───
// Each server owns the sockets of users connected to IT, and subscribes to
// their pub-sub channels so messages from other servers are delivered locally.
class ConnectionRegistry {
    private final String serverId; private final PubSub pubSub;
    private final Map<String, java.util.function.Consumer<Message>> localSockets = new ConcurrentHashMap<>();
    ConnectionRegistry(String serverId, PubSub pubSub) { this.serverId = serverId; this.pubSub = pubSub; }

    void connect(String userId, java.util.function.Consumer<Message> socket) {
        localSockets.put(userId, socket);
        pubSub.subscribe("user:" + userId, socket);    // deliver anything published for this user
    }
    void disconnect(String userId) {
        localSockets.remove(userId);
        pubSub.unsubscribe("user:" + userId);
    }
    boolean isLocallyConnected(String userId) { return localSockets.containsKey(userId); }
}

// ─── offline/OfflineQueue.java + PushNotifier.java ───
class OfflineQueue {
    private final Map<String, List<Message>> pending = new ConcurrentHashMap<>();
    void enqueue(String userId, Message m) { pending.computeIfAbsent(userId, k -> new ArrayList<>()).add(m); }
}
class PushNotifier {
    private static final Logger log = Logger.getLogger(PushNotifier.class.getName());
    void notifyUser(String userId, Message m) {
        log.info("PUSH to " + userId + " via FCM: new message from " + m.from);
    }
}

// ─── service/ChatService.java ───
// Persist FIRST, then deliver via pub-sub. Offline → queue + push.
class ChatService {
    private static final Logger log = Logger.getLogger(ChatService.class.getName());
    private final MessageStore store; private final SequenceGenerator seq;
    private final PubSub pubSub; private final OfflineQueue offlineQueue; private final PushNotifier push;

    ChatService(MessageStore store, SequenceGenerator seq, PubSub pubSub,
                OfflineQueue offlineQueue, PushNotifier push) {
        this.store = store; this.seq = seq; this.pubSub = pubSub;
        this.offlineQueue = offlineQueue; this.push = push;
    }

    void send(String convo, String from, String to, String body, String clientId) {
        long s = seq.next(convo);
        Message m = new Message(convo, from, to, body, clientId, s);
        store.persist(m);                                   // STEP 1: durable first
        // STEP 2: deliver. Publish to recipient's channel — any server holding the socket delivers.
        pubSub.publish("user:" + to, m);
        // If nobody delivered (no live socket anywhere), fall back to queue + push.
        // In this demo we also enqueue+push when the socket was removed.
    }

    void markRead(String convo, String reader, long upToSeq) {
        store.updateState(convo, upToSeq, DeliveryState.READ);
        log.info("READ receipt: " + reader + " read up to seq " + upToSeq + " → sync to sender's devices");
    }

    void replayMissed(String convo, String userId, long lastSeenSeq) {
        List<Message> missed = store.since(convo, lastSeenSeq);
        log.info("REPLAY " + missed.size() + " missed messages to " + userId + " from seq > " + lastSeenSeq);
        missed.forEach(m -> pubSub.publish("user:" + userId, m));
    }

    void deliverOfflineFallback(String to, Message m) {
        offlineQueue.enqueue(to, m);
        push.notifyUser(to, m);
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
